def ingest_file( path: Path, collection_name: str = qdrant.DEFAULT_COLLECTION_NAME, embed_fn: Optional[EmbeddingFn] = None, client: Optional["qdrant.QdrantClient"] = None, domain: Optional[str] = None, ) -> IngestionResult: """Ingest a document into Qdrant with embeddings and metadata payload.
Args: path: Path to document file collection_name: Qdrant collection name (default: "knowledge") embed_fn: Optional custom embedding function client: Optional Qdrant client (creates new if None) domain: Optional domain tag for payload (defaults to file extension)
Returns: IngestionResult with collection name, chunk count, points written, vector size """ # Converts to Markdown, chunks, embeds, upserts to Qdrant with payload: # {text, source_file, section, domain, ingested_at, hash}

@dataclass
class ProviderConfig:
    name: str
    type: str  # "free_tier" or "paid"
    priority: int
    model: Optional[str] = None
    api_key_env: Optional[str] = None

    def api_key(self) -> Optional[str]:
        if self.api_key_env:
            return os.environ.get(self.api_key_env)
        return None

@dataclass
class Settings:
    project_name: str
    environment: str
    workspace: WorkspaceConfig = field(default_factory=WorkspaceConfig)
    providers: List[ProviderConfig] = field(default_factory=list)

app = typer.Typer(help="Memory ingestion and retrieval commands.")

@app.command("add")
def memory_add(
    path: Path = typer.Argument(..., exists=True, readable=True, help="Path to document to ingest"),
    collection: str = typer.Option("knowledge", help="Qdrant collection name"),
) -> None:
    """Ingest a document into memory."""
    result = ingest.ingest_file(path, collection_name=collection)
    typer.echo(f"Ingested {result.chunks} chunk(s) into collection '{result.collection_name}'")
    raise typer.Exit(code=0)

@app.command("search")
def memory_search(
    query: str = typer.Argument(..., help="Natural language query"),
    source: Optional[str] = typer.Option(None, help="Logical source/domain filter"),
    since: Optional[str] = typer.Option(None, help="Optional time filter (e.g., '7d')"),
    k: int = typer.Option(10, help="Number of results (1-50)"),
) -> None:
